#include "model.h"
#include <chrono>
#include <malloc.h>
#include <sys/resource.h>
int main(int argc,char **argv){mallopt(M_DECAY_TIME,0);if(argc<3)return 1;lyra_stems::Model model;auto start=std::chrono::steady_clock::now();if(!model.load(argv[1],argv[2],1))return 2;std::vector<float> pcm(2*LYRA_STEM_INPUT_FRAMES);for(int i=0;i<LYRA_STEM_INPUT_FRAMES;++i)pcm[i*2]=pcm[i*2+1]=float(.3*std::sin(6.283185307179586*440*i/44100));for(int n=0;n<3;++n){auto before=std::chrono::steady_clock::now();if(!model.process(pcm.data(),pcm.size()))return 3;double energy=0;for(float x:model.output())energy+=x*x;std::printf("stem process us=%lld rms=%g\n",(long long)std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now()-before).count(),std::sqrt(energy/pcm.size()));}for(const char *path:{"/proc/self/status","/proc/self/smaps_rollup"}){FILE *f=std::fopen(path,"r");if(f){char line[256];while(std::fgets(line,sizeof(line),f))if(std::strstr(line,"Rss") || std::strstr(line,"Pss"))std::printf("%s",line);std::fclose(f);}}rusage usage{};getrusage(RUSAGE_SELF,&usage);std::printf("maxrss=%ldkB total_ms=%lld\n",usage.ru_maxrss,(long long)std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()-start).count());model.release();}
